            $fakedForBranchPruning['onlyIfNot-' . $onlyIfNotStoreKey] = true;
        }

        if (isset($storeKey)) {
            // We are processing an if condition
            // We cascade the pruning to the depending branches
            $branchStore[$storeKey] = 'Pruned branch';
